/**
 * Patches any world-atlas FeatureCollection in-place so India (356) and all 7 land neighbors
 * (Pakistan 586, Afghanistan 004, China 156, Nepal 524, Bhutan 064, Myanmar 104, Bangladesh 050)
 * form an exact, gap-free, overlap-free topological partition conforming to the Official Map of India
 * published by the Survey of India (Government of India).
 */
export function applyOfficialSurveyOfIndiaBoundaries<
  T extends FeatureCollection<Geometry, { name?: string }>
>(atlas: T): T {
  let indiaFeature: T["features"][number] | null = null;
  const otherFeatures: T["features"] = [];

  for (const feat of atlas.features) {
    const id = String(feat.id ?? "").padStart(3, "0");
    if (id === "356") {
      feat.geometry = {
        type: "MultiPolygon",
        coordinates: INDIA_SOI_MULTIPOLYGON,
      };
      indiaFeature = feat;
    } else if (id === "586") {
      feat.geometry = {
        type: "Polygon",
        coordinates: PAKISTAN_SOI_CLIPPED_RING,
      };
      otherFeatures.push(feat);
    } else if (id === "004") {
      feat.geometry = {
        type: "Polygon",
        coordinates: AFGHANISTAN_SOI_CLIPPED_RING,
      };
      otherFeatures.push(feat);
    } else if (id === "156") {
      feat.geometry = {
        type: "MultiPolygon",
        coordinates: CHINA_SOI_CLIPPED_MULTIPOLYGON,
      };
      otherFeatures.push(feat);
    } else if (id === "524") {
      feat.geometry = {
        type: "Polygon",
        coordinates: NEPAL_SOI_CLIPPED_RING,
      };
      otherFeatures.push(feat);
    } else if (id === "064") {
      feat.geometry = {
        type: "Polygon",
        coordinates: BHUTAN_SOI_CLIPPED_RING,
      };
      otherFeatures.push(feat);
    } else if (id === "104") {
      feat.geometry = {
        type: "Polygon",
        coordinates: MYANMAR_SOI_CLIPPED_RING,
      };
      otherFeatures.push(feat);
    } else if (id === "050") {
      feat.geometry = {
        type: "Polygon",
        coordinates: BANGLADESH_SOI_CLIPPED_RING,
      };
      otherFeatures.push(feat);
    } else {
      otherFeatures.push(feat);
    }
  }

  if (indiaFeature) {
    otherFeatures.push(indiaFeature);
  }
  atlas.features = otherFeatures;
  return atlas;
}
